def comprimir_repeticiones(texto: str) -> str:
    if not texto:
        return ""

    resultado = []
    contador = 1

    for i in range(1, len(texto)):
        if texto[i] == texto[i - 1]:
            contador += 1
        else:
            resultado.append(texto[i - 1])
            resultado.append(str(contador))
            contador = 1

    # Agregar el último grupo
    resultado.append(texto[-1])
    resultado.append(str(contador))

    return "".join(resultado)

def aplanar(datos: list) -> list:
    resultado = []
    for elemento in datos:
        if isinstance(elemento, (list, tuple)):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

import csv
from io import StringIO
from typing import List, Dict

def parsear_ventas(texto: str) -> list[dict]:
    # Split into lines and filter out empty/whitespace-only lines
    lines = [line for line in texto.splitlines() if line.strip()]

    if not lines:
        return []

    # Use csv module to properly handle quoted fields
    reader = csv.reader(StringIO("".join(lines)))

    try:
        header = next(reader)
    except StopIteration:
        return []  # No data rows

    expected_header = ["fecha", "producto", "cantidad", "precio"]
    if header != expected_header:
        raise ValueError(f"Cabecera no válida. Se esperaba {expected_header}, se obtuvo {header}")

    result = []
    for row in reader:
        # Must have exactly 4 fields
        if len(row) != 4:
            raise ValueError("Fila inválida: número de campos no es 4")

        fecha, producto, cantidad_str, precio_str = row

        # Parse cantidad (must be integer)
        try:
            cantidad = int(cantidad_str)
        except ValueError:
            raise ValueError("cantidad debe ser un entero")

        if cantidad < 0:
            raise ValueError("cantidad no puede ser negativa")

        # Parse precio (must be float)
        try:
            precio = float(precio_str)
        except ValueError:
            raise ValueError("precio debe ser un número")

        result.append({
            "fecha": fecha,
            "producto": producto,
            "cantidad": cantidad,
            "precio": precio
        })

    return result

from datetime import datetime

def parsear_fecha(texto: str) -> str:
    # Remove leading/trailing whitespace
    texto = texto.strip()

    if not texto:
        raise ValueError("La fecha está vacía")

    # Format 1: AAAA-MM-DD
    try:
        return datetime.strptime(texto, "%Y-%m-%d").strftime("%Y-%m-%d")
    except ValueError:
        pass

    # Format 2: DD/MM/AAAA
    try:
        return datetime.strptime(texto, "%d/%m/%Y").strftime("%Y-%m-%d")
    except ValueError:
        pass

    # Format 3: D de MES de AAAA
    parts = texto.split()
    if len(parts) != 5:
        raise ValueError("Formato incorrecto para la fecha")

    dia_str, de1, mes_str, de2, año_str = parts

    # Map month name to number (case insensitive)
    meses = {
        "enero": 1, "febrero": 2, "marzo": 3, "abril": 4,
        "mayo": 5, "junio": 6, "julio": 7, "agosto": 8,
        "septiembre": 9, "octubre": 10, "noviembre": 11, "diciembre": 12
    }

    if mes_str.lower() not in meses:
        raise ValueError(f"Mes inválido: {mes_str}")

    try:
        fecha = datetime(int(dia_str), meses[meses[mes_str.lower()]], int(año_str))
    except (ValueError, TypeError):
        raise ValueError("Fecha no válida")

    return fecha.strftime("%Y-%m-%d")

def promedio_movil(valores: list[float], ventura: int) -> list[float]:
    if ventura <= 0:
        return []
    resultado = []
    for i in range(len(valores) - ventura + 1):
        resultado.append(sum(valores[i:i + ventura]) / ventura)
    return resultado

from collections import OrderedDict


class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad <= 0:
            raise ValueError("La capacidad debe ser positiva")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave not in self._datos:
            return None
        # Mover al final para marcar como reciente (propiedad LRU)
        self._datos.move_to_end(clave)
        return self._datos[clave]

    def put(self, clave, valor):
        if clave in self._datos:
            # Si la clave ya existe, actualizar y mover al final
            self._datos[clave] = valor
            self._datos.move_to_end(clave)
        elif len(self._datos) >= self.capacidad:
            # Caché llena, eliminar el elemento más antiguo (primero insertado)
            self._datos.popitem(last=False)
        else:
            # Hay espacio disponible, simplemente agregar
            self._datos[clave] = valor

    def __len__(self):
        return len(self._datos)
